  "style": [
    "modern chamber",
    "minimal piano",
    "subtle electronics"
  ],
  "mood": [
    "intimate",
    "uncertain",
    "grounded"
  ],
  "must_include": [
    "silence or sparse bars around delete moment",
    "motif changes meaning",
    "final action is forward motion without triumph"
  ],
  "must_avoid": [
    "sentimental major-key swell",
    "continuous melody under dialogue",
    "huge climax"
  ],
  "instrument_roles": [
    "piano",
    "solo cello",
    "soft strings",
    "subtle pulse",
    "air texture",
    "low support"
  ],
  "delivery": [
    "36 bars",
    "6 to 8 tracks",
    "dialogue space and controlled registers"
  ],
  "score_focus": [
    "restraint",
    "motif reinterpretation",
    "dialogue support"
  ],
  "mode_a": false
}

